// Every runtime frame between an import and the imported module's evaluation is
// repeated once per level of an import chain, so the size of that path limits
// how deep a chain can get before the stack overflows. With trivial modules on
// Node's default stack, the Node.js dev runtime handles chains about 1300-1500
// deep. Before its instantiation path was flattened it overflowed at about 800.
//
// `generated-chain/<kind>/<n>` modules are generated by the test harness (see
// `GeneratedChainReplacer` in `execution.rs`): each one loads
// `generated-chain/<kind>/<n - 1>` and exports its depth. Scope hoisting is
// disabled in `options.json`, since it would merge the chain into one module.
const CHAIN_DEPTH = 1000

function evaluationFrames(kind) {
  return globalThis.__generatedChainEvaluationFrames?.[kind]
}

it(`evaluates a ${CHAIN_DEPTH} module import chain`, async () => {
  const { depth } = await import('generated-chain/esm/999')
  expect(depth).toBe(CHAIN_DEPTH)
  // Each module was evaluated separately, through the runtime.
  expect(evaluationFrames('esm')).toBeGreaterThanOrEqual(CHAIN_DEPTH)
})

it(`evaluates a ${CHAIN_DEPTH} module require chain`, () => {
  const { depth } = require('generated-chain/cjs/999')
  expect(depth).toBe(CHAIN_DEPTH)
  expect(evaluationFrames('cjs')).toBeGreaterThanOrEqual(CHAIN_DEPTH)
})
